+      refreshTokenTtl: null,
+      signingAlgorithm: null,
+      signingKeyId: null,
+      allowedScopes: [...SUPPORTED_SCOPES],
+      customClaims: {},
+      dpopBoundAccessTokensRequired: false,
+      disabled: false,
+      createdAt: new Date(now),
+      updatedAt: new Date(now),
+      policyVersion: 1,
+      metadata: null,
