+      database,
+      `application:created:${applicationId}`,
+      "application.created",
+      actor.principalId,
+      null,
+      null,
+      { applicationId, name, owner: ownership.owner, resourceIdentifier },
+      now,
+    ),
+    outboxStatement(
+      database,
+      `application:created:outbox:${applicationId}`,
+      "application.created",
+      "application",
+      applicationId,
+      { applicationId, name, resourceIdentifier },
+      now,
+    ),
+  ]);
